import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchRiderById, addRider, updateRiderPI, updateRiderCI, updateRiderFD, updateRiderAC, 
    updateRiderAttachments, fetchRiderAttachmentsById, deleteRiderAttachment, fetchDocumentContentById } from '../../store/reducers/riderSlice';
import {
    Modal, Box, TextField, Button, Typography, Grid2 as Grid, MenuItem,
    IconButton, Tooltip, FormControl, FormLabel, RadioGroup,
    FormControlLabel, Radio, InputLabel, Select
} from '@mui/material';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import Tabs from "../../components/tabPanel/Tabs";
import Panel from "../../components/tabPanel/Panel";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEdit, faSquarePlus, faSquareMinus } from '@fortawesome/free-regular-svg-icons';
import { faDownload } from '@fortawesome/free-solid-svg-icons';
import {
    DataGrid
} from '@mui/x-data-grid';


const RiderFormModal = ({ riderID, vendors, riderDocumentTypes, reloadGrid }) => {

    const [open, setOpen] = useState(false);
    let [formData, setFormData] = useState({
        vendorID: "",
        referenceName: "",
        fullName: "",
        gender: "",
        dateOfBirth: "",
        aadharCardNumber: "",
        panNumber: "",
        bloodGroup: "",
        contactNumber: "",
        emailID: "",
        alternativeContactNumber: "",
        alternativeEmail: "",
        emergencyContactNumber: "",
        emergencyContactPersonID: "",
        emergencyContactRelation: "",
        emergencyContactName: "",
        addressLine1: "",
        addressLine2: "",
        state: "",
        city: "",
        zip: "",
        landmark: "",
        highestDegreeEarned: "",
        previousOrgName: "",
        bankAccountNumber: "",
        bankName: "",
        bankIFSCCode: "",
        uanNumber: "",
        insurancePolicyNumber: "",
        insurerName: "",
        insuranceStartDate: "",
        insuranceEndDate: "",
        familyMemberName: "",
        familyMemberRelation: "",
        familyMemberIDType: "",
        familyMemberID: "",
        familyMemberContact: "",
        isBackgroundVerificationCompleted: false,
        isPhysicalVerificationCompleted: false,
        backgroundVerificationAgencyName: "",
        isAadhaarVerified: false,
        isContactNumberVerified: false,
        additionalNotes: "",
        createdByID: 0,
        createdDate: ""
    });

    const dispatch = useDispatch();
    const [touched, setTouched] = useState({});
    const [documentType, setDocumentType] = useState('');
    const [uploadedFile, setUploadedFile] = useState(null);
    const [attachments, setAttachments] = useState([]);
    const [updateSuccess, setUpdateSuccess] = useState(false);

    useEffect(() => {
        if (riderID && open) {
            getRiderById();
            getRiderAttachments();
        }
    }, [dispatch, riderID, open]);

    const getRiderById = async () => {
        if (riderID) {
            dispatch(fetchRiderById(riderID)).then((response) => {
                const data = response.payload;
                setFormData({
                    ...data,
                    dateOfBirth: data.dateOfBirth ? data.dateOfBirth.split('T')[0] : "",
                    insuranceStartDate: data.insuranceStartDate ? data.insuranceStartDate.split('T')[0] : "",
                    insuranceEndDate: data.insuranceEndDate ? data.insuranceEndDate.split('T')[0] : "",
                    isPhysicalVerificationCompleted: data.isPhysicalVerificationCompleted ? "Yes" : "No",
                    isAadhaarVerified: data.isAadhaarVerified ? "Yes" : "No",
                    isContactNumberVerified: data.isContactNumberVerified ? "Yes" : "No",
                    isBackgroundVerificationCompleted: data.isBackgroundVerificationCompleted ? "Yes" : "No",
                });
            });
        }
    }

    const getRiderAttachments = async () => {
        if (riderID) {
            const response = await dispatch(fetchRiderAttachmentsById(riderID));
            const data = response.payload;
            let attachmentResponse = data.map((item) => ({
                attachmentID: item.attachmentID,
                contentType: item.contentType,
                attachmentType: item.attachmentType,
                attachmentName: item.attachmentName,
                numberOfKB: item.numberOfKB,
                lastModifiedDate: item.lastModifiedDate?.toLocaleDateString(),
            }));
            setAttachments(attachmentResponse);
        }
    }

    useEffect(() => {
        if (updateSuccess) {
            handleClose();
            reloadGrid();
            setUpdateSuccess(false);
        }
    }, [updateSuccess, reloadGrid]);

    const handleOpen = () => setOpen(true);
    const handleClose = () => setOpen(false);

    const handleFileUpload = (e) => {
        const file = e.target.files?.[0] || null;
        setUploadedFile(file);
    };

    const handleDocumentTypeChange = (e) => {
        setDocumentType(e.target.value);
        setUploadedFile(null);
    }

    const getBase64String = (file) => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = () => {
                const base64String = reader.result.split(',')[1]; // Remove the metadata part
                resolve(base64String);
            };
            reader.onerror = (error) => {
                console.error("Error reading file:", error);
                reject(error);
            };
        });
    }

    const handleAddAttachmentFile = async () => {
        if(uploadedFile && documentType) {
            setDocumentType('');
            setUploadedFile(null);

            const data = {
                riderID,
                attachmentTypeID: documentType,
                attachmentType: "",
                attachmentName: uploadedFile.name,
                contentType: uploadedFile.type,
                numberOfKB: uploadedFile.size.toString(),
                content: await getBase64String(uploadedFile),
                loggedInUserID: 1,
                attachmentID: "3fa85f64-5717-4562-b3fc-2c963f66afa6"
            }
            const response = await dispatch(updateRiderAttachments(data));
            if (response.payload) {
                getRiderAttachments();
            }
        }
    }

    const handleDeleteAttachment = (id) => {
        if(id) {
            dispatch(deleteRiderAttachment(id)).then(() => {
                getRiderAttachments();
            });
        }
    }

     const handleDownloadDocument = async (id) => {
        if (id) {
            const response = await dispatch(fetchDocumentContentById(id));
            const data = response.payload;
            if (data) {
                const byteCharacters = atob(data.content);
                const byteNumbers = new Array(byteCharacters.length);
                for (let i = 0; i < byteCharacters.length; i++) {
                    byteNumbers[i] = byteCharacters.charCodeAt(i);
                }
                const byteArray = new Uint8Array(byteNumbers);
                const blob = new Blob([byteArray], { type: data.contentType });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = data.attachmentName;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);
            }
        }
    }

    const handleChange = (e) => {
        const { name, value } = e.target;
        switch (name) {
            case "aadharCardNumber": {
                if (!/^\d*$/.test(value) || value.length > 12) return;
                break;
            }
            case "contactNumber": {
                if (!/^\d*$/.test(value) || value.length > 10) return;
                break;
            }
            case 'isBackgroundVerificationCompleted': {
                if (value === "Yes") {
                    formData.backgroundVerificationAgencyName = "";
                }
                break;
            }
        }

        setFormData({ ...formData, [name]: value });
    };

    const handleBlur = (e) => {
        setTouched({ ...touched, [e.target.name]: true });
    };
    const handleUploadSave = async () => {

    }


    const getFieldError = (field) => {
        return !isFieldValid(field) && touched[field] ? "This field is required" : "";
    };

    const isPanelValid = (fields) => {
        return fields.every((field) => isFieldValid(field));
    };
    const isFieldValid = (field) => {
        if (field === "emailID" || field === "alternativeEmail") {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            return emailRegex.test(formData[field]);
        }
        else if (field === "alternativeContactNumber" || field === "emergencyContactNumber") {
            const contactNumberRegex = /^\d{10}$/;
            return contactNumberRegex.test(formData[field]);
        }
        else if (typeof formData[field] === "string") {
            return formData[field].trim() !== "";
        }
        return formData[field] !== "";
    };
    const handlePISave = async () => {
        try {
            const piData = {
                fullName: formData.fullName,
                vendorID: formData.vendorID,
                referenceName: formData.referenceName,
                gender: formData.gender,
                dateOfBirth: formData.dateOfBirth,
                aadhaarNumber: formData.aadharCardNumber,
                pan: formData.panNumber,
                contactNumber: formData.contactNumber,
                bloodGroup: formData.bloodGroup,
                personalEmailID: formData.emailID,
                loggedInUserID: -1
            }
            if (riderID) {
                let reqObj = { ...piData, riderID };
                await dispatch(updateRiderPI(reqObj));
            } else {

                await dispatch(addRider(piData));
            }
            setUpdateSuccess(true);
        } catch (err) {
            console.error(err);
        } finally {
            handleClose();
        }
    };
    
    const handleCISave = async () => {
        try {
            const ciData = {
                riderID: riderID,
                alternativeContactNumber: formData.alternativeContactNumber,
                alternativeEmail: formData.alternativeEmail,
                emergencyContactName: formData.emergencyContactName,
                emergencyContactRelation: formData.emergencyContactRelation,
                emergencyContactPersonID: formData.emergencyContactPersonID,
                emergencyContactNumber: formData.emergencyContactNumber,
                addressLine1: formData.addressLine1,
                addressLine2: formData.addressLine2,
                state: formData.state,
                city: formData.city,
                zip: formData.zip,
                landmark: formData.landmark,
                highestDegreeEarned: formData.highestDegreeEarned,
                previousOrgName: formData.previousOrgName,
                loggedInUserID: -1
            };

            if (riderID) {
                await dispatch(updateRiderCI(ciData));
                setUpdateSuccess(true);
            }

        } catch (err) {
            console.error(err);
        } finally {
            handleClose();
        }
    };

    const handleFDSave = async () => {
        try {
            const financialData = {
                riderID,
                bankName: formData.bankName,
                bankAccountNumber: formData.bankAccountNumber,
                bankIFSCCode: formData.bankIFSCCode,
                uanNumber: formData.uanNumber,
                insurancePolicyNumber: formData.insurancePolicyNumber,
                insurerName: formData.insurerName,
                insuranceStartDate: formData.insuranceStartDate,
                insuranceEndDate: formData.insuranceEndDate
            };

            if (riderID) {
                await dispatch(updateRiderFD(financialData));
                setUpdateSuccess(true);
            }
        } catch (err) {
            console.error(err);
        } finally {
            handleClose();
        }
    };

    const handleACSave = async () => {
        try {

            const additionalChecksData = {
                riderID,
                isBackgroundVerificationCompleted: formData.isBackgroundVerificationCompleted === "Yes",
                isPhysicalVerificationCompleted: formData.isPhysicalVerificationCompleted === "Yes",
                isAadhaarVerified: formData.isAadhaarVerified === "Yes",
                isContactNumberVerified: formData.isContactNumberVerified === "Yes",
                backgroundVerificationAgencyName: formData.isBackgroundVerificationCompleted === "Yes" ? formData.backgroundVerificationAgencyName : "",
                familyMemberName: formData.familyMemberName,
                familyMemberRelation: formData.familyMemberRelation,
                familyMemberIDType: formData.familyMemberIDType,
                familyMemberID: formData.familyMemberID,
                familyMemberContact: formData.familyMemberContact,
            }
            
            if (riderID) {
                await dispatch(updateRiderAC(additionalChecksData));
                setUpdateSuccess(true);
            }
        } catch (err) {
            console.error(err);
        } finally {
            handleClose();
        }
    };
   
    const columns = [
        { field: 'attachmentType', headerName: 'Document Type', sortable: false, filterable: false, flex: 1 },
        { field: 'attachmentName', headerName: 'Name', sortable: false, filterable: false, flex: 1.5 },
        { field: 'numberOfKB', headerName: 'Size (KB)', sortable: false, filterable: false, flex: 0.5 },
        { field: 'lastModifiedDate', headerName: 'Last Modified Date', sortable: false, filterable: false, flex: 1 },
        {
            field: 'actions',
            headerName: 'Actions',
            flex: 0.5,
            sortable: false, filterable: false,
            renderCell: (params) => (
                <div style={{ display: 'flex' }}>
                    <IconButton
                        color="secondary"
                        size="small"
                        onClick={() => handleDeleteAttachment(params.row.attachmentID)}
                        sx={{ width: "40px", Height: "40px" }}
                    >
                        <Tooltip title="Delete Document" arrow><FontAwesomeIcon icon={faSquareMinus} color='#ff0000' /></Tooltip>
                    </IconButton>
                    <IconButton
                        color="secondary"
                        size="small"
                        onClick={() => handleDownloadDocument(params.row.attachmentID)}
                        sx={{ width: "40px", Height: "40px" }}
                    >
                        <Tooltip title="Download Document" arrow><FontAwesomeIcon icon={faDownload} color='#1976d2' /></Tooltip>
                    </IconButton>
                </div>
            ),
        },
    ]

    return (
        <>
            {
                riderID ?
                    (
                        <IconButton
                            color="primary"
                            size="small"
                            onClick={handleOpen}
                            sx={{ width: "40px", Height: "40px" }}
                        >
                            <Tooltip title="Edit Rider" arrow><FontAwesomeIcon icon={faEdit} /></Tooltip>
                        </IconButton>
                    )
                    : <Button variant="contained" color="primary" onClick={handleOpen}>Add New</Button>
            }
            <Modal
                open={open}
                onClose={handleClose}
                slotProps={{ BackdropProps: { onClick: (e) => e.stopPropagation() } }}
                aria-labelledby="modal-modal-title"
                aria-describedby="modal-modal-description"
            >
                <Box sx={{ top: '50%', left: '50%', transform: 'translate(-50%, -50%)', position: 'absolute', bgcolor: 'background.paper', boxShadow: 24, p: 4, height: 650, width: 1100 }}>
                    <Grid container spacing={3} >
                        <Grid size={6}>
                            <Typography id="modal-title" variant="h6" sx={{ fontWeight: 900 }}>Rider Form</Typography>
                        </Grid>
                        <Grid size={6} sx={{ textAlign: 'right' }}>
                            <CloseRoundedIcon style={{ 'color': "red", 'cursor': "pointer" }} onClick={handleClose} />
                        </Grid>
                        <Tabs selected={0} isReadOnly={!(riderID)} >
                            <Panel title="Personal Information">
                                <Grid container rowSpacing={2} columnSpacing={3} sx={{ paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }}>
                                    <Grid size={5} sx={{ marginTop: 1 }}>
                                        <TextField
                                            fullWidth
                                            label="Full Name"
                                            variant="outlined"
                                            size="small"
                                            name="fullName"
                                            value={formData.fullName}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            error={!isFieldValid("fullName") && touched.fullName}
                                            helperText={getFieldError("fullName")}
                                        />
                                    </Grid>
                                    <Grid size={5} sx={{ marginTop: 1 }} >
                                        <TextField
                                            fullWidth
                                            label="Vendor Name"
                                            variant="outlined"
                                            size="small"
                                            name="vendorID"
                                            value={formData.vendorID}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            error={!isFieldValid("vendorID") && touched.vendorID}
                                            helperText={getFieldError("vendorID")}
                                            select
                                        >
                                            {vendors && vendors.map((vendor) => (
                                                <MenuItem key={vendor.id} value={vendor.id}>
                                                    {vendor.name}
                                                </MenuItem>
                                            ))}
                                        </TextField>
                                    </Grid>
                                    <Grid size={5} sx={{ marginTop: 0.4 }} >
                                        <TextField
                                            fullWidth
                                            label="Reference Name"
                                            variant="outlined"
                                            size="small"
                                            name="referenceName"
                                            value={formData.referenceName}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            error={!isFieldValid("referenceName") && touched.referenceName}
                                            helperText={getFieldError("referenceName")}
                                        />
                                    </Grid>
                                    <Grid size={5} sx={{ marginTop: 1 }}>
                                        <TextField
                                            select
                                            fullWidth
                                            label="Gender"
                                            variant="outlined"
                                            size="small"
                                            name="gender"
                                            value={formData.gender}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            error={!isFieldValid("gender") && touched.gender}
                                            helperText={getFieldError("gender")}
                                        >
                                            <MenuItem value="Male">Male</MenuItem>
                                            <MenuItem value="Female">Female</MenuItem>
                                            <MenuItem value="Other">Other</MenuItem>
                                        </TextField>
                                    </Grid>
                                    <Grid size={5} sx={{ marginTop: 1 }}>
                                        <TextField
                                            fullWidth
                                            label="Date of Birth"
                                            variant="outlined"
                                            size="small"
                                            type="date"
                                            slotProps={{ inputLabel: { shrink: true } }}
                                            name="dateOfBirth"
                                            value={formData.dateOfBirth}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            error={!isFieldValid("dateOfBirth") && touched.dateOfBirth}
                                            helperText={getFieldError("dateOfBirth")}
                                        />
                                    </Grid>
                                    <Grid size={5} sx={{ marginTop: 1 }}>
                                        <TextField
                                            fullWidth
                                            label="Aadhaar Number"
                                            variant="outlined"
                                            size="small"
                                            name="aadharCardNumber"
                                            value={formData.aadharCardNumber}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            type='number'
                                            error={touched.aadharCardNumber && (!/^\d{12}$/.test(formData.aadharCardNumber) || formData.aadharCardNumber.length !== 12)}
                                            helperText={touched.aadharCardNumber && (!/^\d{12}$/.test(formData.aadharCardNumber) || formData.aadharCardNumber.length !== 12) ? "Aadhaar Number must be a 12-digit number" : ""}
                                        />
                                    </Grid>
                                    <Grid size={5} sx={{ marginTop: 1 }}>
                                        <TextField
                                            fullWidth
                                            label="Pan Number"
                                            variant="outlined"
                                            size="small"
                                            name="panNumber"
                                            value={formData.panNumber}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            error={!isFieldValid("panNumber") && touched.panNumber}
                                            helperText={getFieldError("panNumber")}
                                        />
                                    </Grid>
                                    <Grid size={5} sx={{ marginTop: 1 }}>
                                        <TextField
                                            select
                                            fullWidth
                                            label="Blood Group"
                                            variant="outlined"
                                            size="small"
                                            name="bloodGroup"
                                            value={formData.bloodGroup}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            error={!isFieldValid("bloodGroup") && touched.bloodGroup}
                                            helperText={getFieldError("bloodGroup")}
                                        >
                                            <MenuItem value="A+">A+</MenuItem>
                                            <MenuItem value="B+">B+</MenuItem>
                                            <MenuItem value="AB+">AB+</MenuItem>
                                            <MenuItem value="O+">O+</MenuItem>
                                            <MenuItem value="A-">A-</MenuItem>
                                            <MenuItem value="B-">B-</MenuItem>
                                            <MenuItem value="AB-">AB-</MenuItem>
                                            <MenuItem value="O-">O-</MenuItem>
                                        </TextField>
                                    </Grid>
                                    <Grid size={5} sx={{ marginTop: 1 }}>
                                        <TextField
                                            fullWidth
                                            label="Contact Number"
                                            variant="outlined"
                                            size="small"
                                            name="contactNumber"
                                            value={formData.contactNumber}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            error={touched.contactNumber && (!/^\d{10}$/.test(formData.contactNumber) || formData.contactNumber.length !== 10)}
                                            helperText={touched.contactNumber && (!/^\d{10}$/.test(formData.contactNumber) || formData.contactNumber.length !== 10) ? "Contact Number must be a 10-digit number" : ""}
                                            type='number'
                                            slotProps={{ htmlInput: { maxLength: 10 } }}
                                        />
                                    </Grid>
                                    <Grid size={5} sx={{ marginTop: 1 }}>
                                        <TextField
                                            fullWidth
                                            label="Email ID"
                                            variant="outlined"
                                            size="small"
                                            name="emailID"
                                            value={formData.emailID}
                                            onChange={handleChange}
                                            onBlur={handleBlur}
                                            required
                                            error={!isFieldValid("emailID") && touched.emailID}
                                            helperText={getFieldError("emailID")}
                                        />
                                    </Grid>
                                    <Grid size={10} sx={{ mt: 2, mb: 2 }}>
                                        <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                                            <Button
                                                variant="contained"
                                                size="small"
                                                color="primary"
                                                onClick={() => handlePISave()}
                                                disabled={!isPanelValid(["fullName", "vendorID", "referenceName", "gender", "dateOfBirth", "aadharCardNumber", "panNumber", "contactNumber", "bloodGroup", "emailID"])}
                                            >
                                                Save
                                            </Button>
                                        </Box>
                                    </Grid>
                                </Grid>
                            </Panel>
                            <Panel title="Contact Information" >
                                <Box sx={{ overflowY: 'auto', maxHeight: 350 }}>
                                    <Typography variant="h7" sx={{ paddingLeft: 5, marginBottom: 2, fontWeight: "bold" }}>
                                        Alternative Contact Section
                                    </Typography>
                                    <Grid container rowSpacing={1} columnSpacing={3} sx={{ paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }}>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Alternative Contact Number"
                                                variant="outlined"
                                                size="small"
                                                name="alternativeContactNumber"
                                                type="number"
                                                value={formData.alternativeContactNumber}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("alternativeContactNumber") && touched.alternativeContactNumber}
                                                helperText={getFieldError("alternativeContactNumber")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }} >
                                            <TextField
                                                fullWidth
                                                label="Alternative Email"
                                                variant="outlined"
                                                size="small"
                                                name="alternativeEmail"
                                                value={formData.alternativeEmail}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("alternativeEmail") && touched.alternativeEmail}
                                                helperText={getFieldError("alternativeEmail")}
                                            />
                                        </Grid>
                                    </Grid>
                                    <Typography variant="h7" sx={{ paddingLeft: 5, marginBottom: 2, fontWeight: "bold" }}>
                                        Emergency Contact
                                    </Typography>
                                    <Grid container rowSpacing={1} columnSpacing={3} sx={{ paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }}>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Emergency Contact Name"
                                                variant="outlined"
                                                size="small"
                                                name="emergencyContactName"
                                                value={formData.emergencyContactName}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("emergencyContactName") && touched.emergencyContactName}
                                                helperText={getFieldError("emergencyContactName")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }} >
                                            <TextField
                                                fullWidth
                                                label="Emergency Contact Relation"
                                                variant="outlined"
                                                size="small"
                                                name="emergencyContactRelation"
                                                value={formData.emergencyContactRelation}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("emergencyContactRelation") && touched.emergencyContactRelation}
                                                helperText={getFieldError("emergencyContactRelation")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }} >
                                            <TextField
                                                fullWidth
                                                label="Emergency Contact ID"
                                                variant="outlined"
                                                size="small"
                                                name="emergencyContactPersonID"
                                                value={formData.emergencyContactPersonID}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("emergencyContactPersonID") && touched.emergencyContactPersonID}
                                                helperText={getFieldError("emergencyContactPersonID")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1, mb: 1 }} >
                                            <TextField
                                                fullWidth
                                                label="Emergency Contact Phone"
                                                variant="outlined"
                                                size="small"
                                                type="number"
                                                name="emergencyContactNumber"
                                                value={formData.emergencyContactNumber}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("emergencyContactNumber") && touched.emergencyContactNumber}
                                                helperText={getFieldError("emergencyContactNumber")}
                                            />
                                        </Grid>
                                    </Grid>
                                    <Typography variant="h7" sx={{ paddingLeft: 5, marginBottom: 2, fontWeight: "bold" }}>
                                        Address
                                    </Typography>
                                    <Grid container rowSpacing={1} columnSpacing={3} sx={{ paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }}>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Address Line 1"
                                                variant="outlined"
                                                size="small"
                                                name="addressLine1"
                                                value={formData.addressLine1}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("addressLine1") && touched.addressLine1}
                                                helperText={getFieldError("addressLine1")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }} >
                                            <TextField
                                                fullWidth
                                                label="Address Line 2"
                                                variant="outlined"
                                                size="small"
                                                name="addressLine2"
                                                value={formData.addressLine2}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("addressLine2") && touched.addressLine2}
                                                helperText={getFieldError("addressLine2")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }} >
                                            <TextField
                                                fullWidth
                                                label="State"
                                                variant="outlined"
                                                size="small"
                                                name="state"
                                                value={formData.state}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("state") && touched.state}
                                                helperText={getFieldError("state")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }} >
                                            <TextField
                                                fullWidth
                                                label="City"
                                                variant="outlined"
                                                size="small"
                                                name="city"
                                                value={formData.city}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("city") && touched.city}
                                                helperText={getFieldError("city")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }} >
                                            <TextField
                                                fullWidth
                                                label="Zip"
                                                variant="outlined"
                                                size="small"
                                                name="zip"
                                                type="number"
                                                value={formData.zip}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("zip") && touched.zip}
                                                helperText={getFieldError("zip")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Landmark"
                                                variant="outlined"
                                                size="small"
                                                name="landmark"
                                                value={formData.landmark}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("landmark") && touched.landmark}
                                                helperText={getFieldError("landmark")}
                                            />
                                        </Grid>
                                    </Grid>
                                    <Typography variant="h7" sx={{ paddingLeft: 5, marginBottom: 2, fontWeight: "bold" }}>
                                        Other Info
                                    </Typography>
                                    <Grid container rowSpacing={1} columnSpacing={3} sx={{ paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }}>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Highest Degree Earned"
                                                variant="outlined"
                                                size="small"
                                                name="highestDegreeEarned"
                                                value={formData.highestDegreeEarned}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                sx={{ height: 32 }}
                                                error={!isFieldValid("highestDegreeEarned") && touched.highestDegreeEarned}
                                                helperText={getFieldError("highestDegreeEarned")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Last Company Name"
                                                variant="outlined"
                                                size="small"
                                                name="previousOrgName"
                                                value={formData.previousOrgName}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("previousOrgName") && touched.previousOrgName}
                                                helperText={getFieldError("previousOrgName")}
                                            />
                                        </Grid>
                                        <Grid size={10} sx={{ mt: 2, mb: 2 }}>
                                            <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                                                <Button
                                                    variant="contained"
                                                    size="small"
                                                    color="primary"
                                                    onClick={() => handleCISave()}
                                                    disabled={!isPanelValid(["alternativeContactNumber", "alternativeEmail", "emergencyContactName", "emergencyContactRelation", "emergencyContactPersonID", "emergencyContactNumber", "addressLine1", "addressLine2", "state", "city", "zip", "landmark", "highestDegreeEarned", "previousOrgName"])}
                                                >
                                                    Save
                                                </Button>
                                            </Box>
                                        </Grid>
                                    </Grid>
                                </Box>
                            </Panel>
                            <Panel title="Financial Details">
                                <Box sx={{ overflowY: 'auto', maxHeight: 350 }}>
                                    {/* Bank Account Details */}
                                    <Typography variant="h7" sx={{ paddingLeft: 5, marginBottom: 2, fontWeight: "bold" }}>
                                        Bank Account Details
                                    </Typography>
                                    <Grid container rowSpacing={1} columnSpacing={3} sx={{ paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }} >
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Bank Name"
                                                variant="outlined"
                                                size="small"
                                                name="bankName"
                                                value={formData.bankName}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("bankName") && touched.bankName}
                                                helperText={getFieldError("bankName")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Bank Account Number"
                                                variant="outlined"
                                                size="small"
                                                name="bankAccountNumber"
                                                value={formData.bankAccountNumber}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("bankAccountNumber") && touched.bankAccountNumber}
                                                helperText={getFieldError("bankAccountNumber")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="IFSC Code"
                                                variant="outlined"
                                                size="small"
                                                name="bankIFSCCode"
                                                value={formData.bankIFSCCode}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("bankIFSCCode") && touched.bankIFSCCode}
                                                helperText={getFieldError("bankIFSCCode")}
                                            />
                                        </Grid>
                                    </Grid>

                                    {/* EPF Details */}
                                    <Typography variant="h7" sx={{ paddingLeft: 5, marginBottom: 1, fontWeight: "bold" }}>
                                        EPF Details
                                    </Typography>
                                    <Grid container rowSpacing={1} columnSpacing={3} sx={{ paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }}>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="UAN Number"
                                                variant="outlined"
                                                size="small"
                                                type="number"
                                                name="uanNumber"
                                                value={formData.uanNumber}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("uanNumber") && touched.uanNumber}
                                                helperText={getFieldError("uanNumber")}
                                            />
                                        </Grid>
                                    </Grid>

                                    {/* Insurance Details */}
                                    <Typography variant="h7" sx={{ paddingLeft: 5, marginBottom: 1, fontWeight: "bold" }}>
                                        Insurance Details
                                    </Typography>
                                    <Grid container rowSpacing={1} columnSpacing={3} sx={{ paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }}>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Policy Number"
                                                variant="outlined"
                                                size="small"
                                                name="insurancePolicyNumber"
                                                value={formData.insurancePolicyNumber}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("insurancePolicyNumber") && touched.insurancePolicyNumber}
                                                helperText={getFieldError("insurancePolicyNumber")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField
                                                fullWidth
                                                label="Insurer Name"
                                                variant="outlined"
                                                size="small"
                                                name="insurerName"
                                                value={formData.insurerName}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("insurerName") && touched.insurerName}
                                                helperText={getFieldError("insurerName")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 2 }}>
                                            <TextField
                                                fullWidth
                                                label="Start Date"
                                                variant="outlined"
                                                size="small"
                                                type="date"
                                                slotProps={{ inputLabel: { shrink: true } }}
                                                name="insuranceStartDate"
                                                value={formData.insuranceStartDate}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("insuranceStartDate") && touched.insuranceStartDate}
                                                helperText={getFieldError("insuranceStartDate")}
                                            />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 2 }}>
                                            <TextField
                                                fullWidth
                                                label="End Date"
                                                variant="outlined"
                                                size="small"
                                                type="date"
                                                slotProps={{ inputLabel: { shrink: true } }}
                                                name="insuranceEndDate"
                                                value={formData.insuranceEndDate}
                                                onChange={handleChange}
                                                onBlur={handleBlur}
                                                required
                                                error={!isFieldValid("insuranceEndDate") && touched.insuranceEndDate}
                                                helperText={getFieldError("insuranceEndDate")}
                                            />
                                        </Grid>
                                    </Grid>
                                    <Grid size={10} sx={{ mt: 2, mb: 2 }}>
                                        <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                                            <Button
                                                variant="contained"
                                                size="small"
                                                color="primary"
                                                onClick={() => handleFDSave()}
                                                disabled={!isPanelValid(["bankName", "bankAccountNumber", "bankIFSCCode", "uanNumber", "insurancePolicyNumber", "insurerName", "insuranceStartDate", "insuranceEndDate"])}  
                                            >
                                                Save
                                            </Button>
                                        </Box>
                                    </Grid>
                                </Box>
                            </Panel>
                            <Panel title="Additional Checks">
                                <Box sx={{ overflowY: 'auto', maxHeight: 350 }}>
                                    {/* Family Member Details */}
                                    <Typography variant="h7" sx={{ paddingLeft: 5, marginBottom: 2, fontWeight: "bold" }}>
                                        Family Member Details
                                    </Typography>
                                    <Grid container rowSpacing={1} columnSpacing={3} sx={{ mb: 2, paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }}>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField fullWidth label="Name" variant="outlined" size="small" name="familyMemberName" error={!isFieldValid("familyMemberName") && touched.familyMemberName} helperText={getFieldError("familyMemberName")} value={formData.familyMemberName} onChange={handleChange} onBlur={handleBlur} required />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField fullWidth label="Relation" variant="outlined" size="small" name="familyMemberRelation" error={!isFieldValid("familyMemberRelation") && touched.familyMemberRelation} value={formData.familyMemberRelation} helperText={getFieldError("familyMemberRelation")} onChange={handleChange} onBlur={handleBlur} required />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField fullWidth label="ID Type" variant="outlined" size="small" name="familyMemberIDType" error={!isFieldValid("familyMemberIDType") && touched.familyMemberIDType} value={formData.familyMemberIDType} helperText={getFieldError("familyMemberIDType")} onChange={handleChange} onBlur={handleBlur} required />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField fullWidth label="ID Number" variant="outlined" size="small" name="familyMemberID" error={!isFieldValid("familyMemberID") && touched.familyMemberID} value={formData.familyMemberID} helperText={getFieldError("familyMemberID")} onChange={handleChange} onBlur={handleBlur} required />
                                        </Grid>
                                        <Grid size={5} sx={{ marginTop: 1 }}>
                                            <TextField fullWidth label="Contact Number" variant="outlined" size="small" name="familyMemberContact" error={!isFieldValid("familyMemberContact") && touched.familyMemberContact} helperText={getFieldError("familyMemberContact")} value={formData.familyMemberContact} onChange={handleChange} onBlur={handleBlur} required />
                                        </Grid>
                                    </Grid>

                                    {/* Background Verification */}
                                    <Typography variant="h7" sx={{ paddingLeft: 5, marginBottom: 2, fontWeight: "bold" }}>
                                        Background Verification
                                    </Typography>
                                    <Grid container rowSpacing={2} columnSpacing={3} sx={{ paddingLeft: 5, maxHeight: 400, backgroundColor: "transparent" }}>
                                        <Grid size={10}>
                                            <FormControl component="fieldset">
                                                <FormLabel component="legend">Physical Verification Completed</FormLabel>
                                                <RadioGroup
                                                    row
                                                    aria-label="physical-verification"
                                                    name="isPhysicalVerificationCompleted"
                                                    value={formData.isPhysicalVerificationCompleted ?? "No"}
                                                    onChange={handleChange}
                                                >
                                                    <FormControlLabel value="Yes" control={<Radio />} label="Yes" />
                                                    <FormControlLabel value="No" control={<Radio />} label="No" />
                                                </RadioGroup>
                                            </FormControl>
                                        </Grid>
                                        <Grid size={10}>
                                            <FormControl component="fieldset">
                                                <FormLabel component="legend">is Aadhaar Verified?</FormLabel>
                                                <RadioGroup
                                                    row
                                                    aria-label="Aadhaar-verification"
                                                    name="isAadhaarVerified"
                                                    value={formData.isAadhaarVerified ?? "No"}
                                                    onChange={handleChange}
                                                >
                                                    <FormControlLabel value="Yes" control={<Radio />} label="Yes" />
                                                    <FormControlLabel value="No" control={<Radio />} label="No" />
                                                </RadioGroup>
                                            </FormControl>
                                        </Grid>
                                        <Grid size={10}>
                                            <FormControl component="fieldset">
                                                <FormLabel component="legend">is Contact Number Verified?</FormLabel>
                                                <RadioGroup
                                                    row
                                                    aria-label="Contact-verification"
                                                    name="isContactNumberVerified"
                                                    value={formData.isContactNumberVerified ?? "No"}
                                                    onChange={handleChange}
                                                >
                                                    <FormControlLabel value="Yes" control={<Radio />} label="Yes" />
                                                    <FormControlLabel value="No" control={<Radio />} label="No" />
                                                </RadioGroup>
                                            </FormControl>
                                        </Grid>
                                        <Grid size={10}>
                                            <FormControl component="fieldset" >
                                                <FormLabel component="legend">Background Verification Completed</FormLabel>
                                                <RadioGroup
                                                    row
                                                    aria-label="background-verification"
                                                    name="isBackgroundVerificationCompleted"
                                                    value={formData.isBackgroundVerificationCompleted ?? "No"}
                                                    onChange={handleChange}
                                                >
                                                    <FormControlLabel value="Yes" control={<Radio />} labelPlacement="end" label="Yes" />
                                                    <FormControlLabel value="No" control={<Radio />} labelPlacement="end" label="No" />
                                                </RadioGroup>
                                            </FormControl>
                                        </Grid>
                                        {
                                            formData.isBackgroundVerificationCompleted === "Yes" &&
                                            <>
                                                <Grid size={5}>
                                                    <TextField
                                                        fullWidth
                                                        label="Agency Name"
                                                        variant="outlined"
                                                        size="small"
                                                        name="backgroundVerificationAgencyName"
                                                        value={formData.backgroundVerificationAgencyName}
                                                        onChange={handleChange}
                                                        onBlur={handleBlur}
                                                        required
                                                        error={!isFieldValid("backgroundVerificationAgencyName") && touched.backgroundVerificationAgencyName}
                                                        helperText={getFieldError("backgroundVerificationAgencyName")}
                                                        maxLength={80}
                                                    />
                                                </Grid>

                                            </>
                                        }
                                        {
                                            riderID && (
                                                <Grid size={10} sx={{ mt: 2, mb: 2 }}>
                                                    <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                                                        <Button
                                                            variant="contained"
                                                            size="small"
                                                            color="primary"
                                                            onClick={() => handleACSave()}
                                                            disabled={!isPanelValid(["familyMemberName", "familyMemberRelation", "familyMemberIDType", "familyMemberID", "familyMemberContact", "isPhysicalVerificationCompleted", "isAadhaarVerified", "isContactNumberVerified", "isBackgroundVerificationCompleted"])}
                                                        >
                                                            Save
                                                        </Button>
                                                    </Box>
                                                </Grid>
                                            )
                                        }
                                    </Grid>

                                </Box>
                            </Panel>
                            <Panel title="Uploads">
                                <Grid container rowSpacing={0} columnSpacing={3} sx={{ paddingLeft: 5, overflowY: "auto", maxHeight: 400, backgroundColor: "transparent" }}>
                                    <Typography variant="h7" sx={{ fontWeight: "bold" }}>Upload Rider Documents</Typography>
                                    <Grid container rowSpacing={0} columnSpacing={3} size={12} sx={{ mt: 2 }}>
                                        <Grid size={5}>
                                            <FormControl fullWidth >
                                                <InputLabel id="document-type-label">Document Type</InputLabel>
                                                <Select
                                                    size="small"
                                                    labelId="document-type-label"
                                                    id="document-type"
                                                    label="Document Type"
                                                    value={documentType}
                                                    onChange={handleDocumentTypeChange}
                                                >
                                                    {
                                                        riderDocumentTypes && riderDocumentTypes.map((document) => (
                                                            <MenuItem key={document.documentTypeID} value={document.documentTypeID}>
                                                                {document.documentType}
                                                            </MenuItem>
                                                        ))
                                                    }
                                                </Select>
                                            </FormControl>
                                        </Grid>
                                        <Grid size={3}>
                                            <TextField
                                                fullWidth
                                                size="small"
                                                disabled
                                                value={uploadedFile ? uploadedFile.name : ''}
                                                placeholder="No file chosen"
                                                sx={{ mt: 0, mb: 0 }}
                                            />
                                        </Grid>
                                        <Grid size={2}>
                                            <Button
                                                variant="contained"
                                                component="label"
                                                disabled={documentType === ""}
                                            >
                                                Browse
                                                <input
                                                    type="file"
                                                    hidden
                                                    onChange={handleFileUpload}
                                                />
                                            </Button>
                                        </Grid>
                                        <Grid size={1}>
                                            <FontAwesomeIcon icon={faSquarePlus}
                                                size='2x'
                                                color={(documentType && uploadedFile) ? 'green' : 'gray'}
                                                onClick={handleAddAttachmentFile}
                                                style={{ cursor: (documentType && uploadedFile) ? "pointer" : "default" }}
                                                disabled={!(documentType || uploadedFile)}
                                            />
                                        </Grid>
                                    </Grid>
                                    <Box gridColumn="span 12" sx={{ mt: 6 }}>
                                        <Typography variant="h7" sx={{ fontWeight: "bold" }}>Uploaded Documents</Typography>
                                    </Box>
                                    
                                    <Grid container rowSpacing={0} columnSpacing={3} size={12} sx={{mt: 2}}>
                                        <Grid size={11}>
                                            <DataGrid
                                                rows={attachments}
                                                columns={columns}
                                                rowHeight={30}
                                                disableSelectionOnClick
                                                getRowId={(row) => row.attachmentID}
                                                hideFooterPagination={true}
                                            />
                                        </Grid>
                                    </Grid>

                                    <Grid container size={12}>
                                        <Grid size={6}></Grid>
                                        <Grid size={5} sx={{ textAlign: 'right', m: 2 }}>
                                            <Button
                                                variant="contained"
                                                size="small"
                                                color="primary"
                                                onClick={() => handleUploadSave()}
                                            >
                                                Save
                                            </Button>
                                        </Grid>

                                    </Grid>
                                </Grid>
                            </Panel>
                        </Tabs>
                    </Grid>
                </Box>
            </Modal>
        </>
    )
}

export default RiderFormModal;